-- RF-102, RF-103, RF-104: unpublished drafts only. Run in SQL Editor as postgres.
-- No schema changes, releases, assignments, or edits to existing courses.
begin;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "b24247d7-0237-51ca-9f36-82037a9cc61d", "slug": "rf-102-retail-terms-and-hardware-vocabulary", "version": 1, "title": "Retail Terms & Hardware Vocabulary", "description": "Learn the words used in a hardware store. Use them to find products, understand daily tasks, and communicate clearly with customers and coworkers.", "category": "Retail Foundations", "passing_percent": 80}, "lessons": [{"id": "0ab673a6-d189-5fb3-8d65-b55d654d39c9", "position": 1, "title": "Speaking the Language of the Store", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "New employees hear many new words on their first shift. Clear terms help the team avoid mistakes. They also help customers feel understood."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Everyday retail terms"}, {"type": "paragraph", "text": "A department is a group of related products. Paint and plumbing are examples. An aisle is a walkway between shelves. A bay is one section of shelving. A bin is a container or small storage location. A display presents products for customers to see."}, {"type": "heading", "text": "How products move"}, {"type": "paragraph", "text": "Receiving means checking products delivered to the store. Stocking means placing products in their assigned locations. Replenishment means adding more products to a shelf or display. A return is merchandise brought back by a customer under the store’s return policy."}, {"type": "heading", "text": "Store paperwork and labels"}, {"type": "paragraph", "text": "A price tag shows a selling price. A shelf label identifies a product and may show its price. A receipt records a sale. A purchase order is a business record used to request products from a supplier. The exact forms vary by store."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A coworker says, “Please replenish the fastener bins in bay three.” The employee finds the correct shelving section and adds the right products to the assigned bins."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Ask a coworker to show you the store’s aisle, bay, and bin labels."}, {"type": "bullet", "text": "Repeat an unfamiliar instruction in your own words."}, {"type": "bullet", "text": "Check product labels before stocking."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Treating an aisle number and a bay number as the same thing. Ask how your store labels each area."}, {"type": "bullet", "text": "Assuming every store uses the same terms. Learn the terms used by your team."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a manager or experienced coworker when a location code is unclear. Do not move merchandise based on a guess."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Ask a coworker to show you the store’s aisle, bay, and bin labels."}, {"type": "bullet", "text": "Repeat an unfamiliar instruction in your own words."}, {"type": "bullet", "text": "Ask a manager or experienced coworker when a location code is unclear."}, {"type": "heading", "text": "Unscored lesson practice — RF-102-P01"}, {"type": "paragraph", "text": "Question: A coworker asks you to replenish a display. What does replenish mean?"}, {"type": "bullet", "text": "A. Remove the display."}, {"type": "bullet", "text": "B. Add products to replace what has sold."}, {"type": "bullet", "text": "C. Change all product prices."}, {"type": "bullet", "text": "D. Process a customer return."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: Replenish means add more merchandise to a shelf or display. It does not mean change prices or process returns."}, {"type": "paragraph", "text": "Scoring: Unscored. The answer and explanation appear after the question."}]}, {"id": "62c52ead-82e8-5075-8f57-082e7135ef26", "position": 2, "title": "Inventory Words You Will Hear", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Inventory words appear in conversations, labels, and store systems. You need to understand them before you can answer stock questions."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Item identifiers"}, {"type": "paragraph", "text": "A SKU is a stock keeping unit. It is an identifier a business uses to track an item. A UPC is a Universal Product Code. It is commonly shown as a barcode number on retail packaging. A store SKU and a UPC may be different. Some products have more than one barcode or packaging option."}, {"type": "heading", "text": "Stock and availability"}, {"type": "paragraph", "text": "On-hand quantity is the number recorded in the inventory system. Available quantity may account for reserved or committed stock. Stores calculate these values in different ways. Out of stock means the item is not currently available for sale at that location. Backorder means an item has been ordered but is waiting for supply. Not every store uses backorders."}, {"type": "heading", "text": "Ordering terms"}, {"type": "paragraph", "text": "A special order is a product ordered for a specific customer request. A lead time is the expected time between ordering and receiving an item. An inventory count checks the actual number of items. An inventory adjustment corrects a recorded quantity after the store verifies a difference."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "The system shows two boxes of screws on hand. The shelf is empty. An employee checks approved storage locations and asks receiving for help. They do not promise the customer that two boxes are ready to buy."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Use “the system shows” when describing an unverified quantity."}, {"type": "bullet", "text": "Check approved locations before confirming availability."}, {"type": "bullet", "text": "Explain that special-order timing is an estimate until the store confirms it."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Confusing SKU with UPC. Check the field label in the system."}, {"type": "bullet", "text": "Treating on-hand quantity as proof that an item is on the shelf. Verify the item."}, {"type": "bullet", "text": "Promising an arrival date from an unconfirmed lead time."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask an inventory lead or manager about quantity differences, reserved stock, and order status. Follow the store’s process for adjustments."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Use “the system shows” when describing an unverified quantity."}, {"type": "bullet", "text": "Check approved locations before confirming availability."}, {"type": "bullet", "text": "Ask an inventory lead or manager about quantity differences, reserved stock, and order status."}, {"type": "heading", "text": "Unscored lesson practice — RF-102-P02"}, {"type": "paragraph", "text": "Question: A customer asks for an item. Your system shows four on hand, but the shelf is empty. What should you say?"}, {"type": "bullet", "text": "A. “We have four. They are ready for you.”"}, {"type": "bullet", "text": "B. “We are sold out forever.”"}, {"type": "bullet", "text": "C. “The system shows four. Let me verify where they are.”"}, {"type": "bullet", "text": "D. “The UPC must be wrong.”"}, {"type": "paragraph", "text": "Answer: C"}, {"type": "paragraph", "text": "Explanation: On-hand quantity is a system record. Verify the actual stock before making a promise."}, {"type": "paragraph", "text": "Scoring: Unscored. The answer and explanation appear after the question."}]}, {"id": "27618e2f-870f-5cc5-9f4a-a4db8ddbd1c6", "position": 3, "title": "Product Names, Sizes, and Units", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Hardware products often look alike. Small differences in size or material can change how a product works. Reading the label is an important skill."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Common product families"}, {"type": "paragraph", "text": "A fastener joins materials. Screws, nails, nuts, and bolts are fasteners. A fitting connects parts of a system. Plumbing fittings are one example. A consumable is used up during work. Sandpaper and drill bits may need regular replacement. A hand tool uses human effort. A power tool uses a motor or another power source."}, {"type": "heading", "text": "Measurements and labels"}, {"type": "paragraph", "text": "Length, width, and diameter describe different dimensions. Diameter measures across a circle through its center. Gauge is a size designation used for some products. Its meaning depends on the product category. A thread is the spiral ridge on a screw or bolt. A thread size helps identify a matching fastener. The numbers and units on the package matter."}, {"type": "heading", "text": "Units and package counts"}, {"type": "paragraph", "text": "Stores sell products by each, pair, pack, foot, gallon, or other units. A price per each is not the same as a price per pack. Nominal size is a common name for a material size. It may differ from the actual measured size. Lumber is one example. Check the label and product specifications."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks for “a half-inch bolt.” The employee asks for the old bolt or package. They check diameter, length, thread information, and grade or strength markings as needed. They do not choose a bolt based on length alone."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Read the full product label."}, {"type": "bullet", "text": "Confirm the unit of sale before quoting a price."}, {"type": "bullet", "text": "Ask for the old part, package, or a clear photo when available."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Assuming two similar-looking fasteners are interchangeable. Check the full specifications."}, {"type": "bullet", "text": "Confusing diameter with length. Identify each measurement."}, {"type": "bullet", "text": "Assuming nominal and actual lumber sizes are equal. Verify the dimensions."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a knowledgeable coworker or consult manufacturer specifications when strength, compatibility, load, electrical ratings, or other safety factors matter. Refer installation decisions to a qualified professional when appropriate."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Read the full product label."}, {"type": "bullet", "text": "Confirm the unit of sale before quoting a price."}, {"type": "bullet", "text": "Ask a knowledgeable coworker or consult manufacturer specifications when strength, compatibility, load, electrical ratings, or other safety factors matter."}, {"type": "heading", "text": "Unscored lesson practice — RF-102-P03"}, {"type": "paragraph", "text": "Question: A customer asks for a replacement bolt. Which detail is useful to confirm?"}, {"type": "bullet", "text": "A. Only the color of the shelf label."}, {"type": "bullet", "text": "B. Only the price."}, {"type": "bullet", "text": "C. Only the aisle number."}, {"type": "bullet", "text": "D. The diameter, length, and thread information."}, {"type": "paragraph", "text": "Answer: D"}, {"type": "paragraph", "text": "Explanation: Fasteners can differ in diameter, length, and thread. Matching these details is more useful than matching appearance alone."}, {"type": "paragraph", "text": "Scoring: Unscored. The answer and explanation appear after the question."}]}, {"id": "bcd656c7-9600-58b9-bc2c-81deee52f83e", "position": 4, "title": "Department Vocabulary", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers may use everyday words instead of product names. Department vocabulary helps you ask better questions and find the right team member."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Paint and decorating"}, {"type": "paragraph", "text": "Primer prepares a surface for a coating. Sheen describes how shiny a paint finish looks. Roller cover is the sleeve that holds paint on a roller frame. Caulk fills certain gaps or joints. Products have different uses. Read the label."}, {"type": "heading", "text": "Plumbing and electrical"}, {"type": "paragraph", "text": "A shutoff valve controls water flow. A supply line carries water to a fixture. A coupling joins two compatible pipe or tubing sections. An outlet is a place to connect electrical equipment. A breaker is a protective device in an electrical circuit. Employees should not diagnose electrical hazards or direct unqualified work."}, {"type": "heading", "text": "Lawn, garden, and tools"}, {"type": "paragraph", "text": "Mulch covers soil. Potting mix is a growing medium for containers. Trimmer line is cutting line used by certain string trimmers. A driver bit turns compatible screws. A drill bit makes holes in suitable material. Check tool and accessory compatibility before recommending a product."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks for “the string for my weed eater.” The employee recognizes that the customer may mean trimmer line. They ask for the model or the old package before checking compatible sizes."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Translate the customer’s everyday words into possible product terms."}, {"type": "bullet", "text": "Ask for a model number when fit or compatibility matters."}, {"type": "bullet", "text": "Direct the customer to the right department or coworker."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Assuming all products with similar names have the same purpose. Read labels."}, {"type": "bullet", "text": "Treating a familiar brand name as an exact product description. Ask for details."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a department specialist or consult official product instructions for chemical use, electrical work, plumbing repairs, and equipment compatibility. Do not provide unverified safety advice."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Translate the customer’s everyday words into possible product terms."}, {"type": "bullet", "text": "Ask for a model number when fit or compatibility matters."}, {"type": "bullet", "text": "Ask a department specialist or consult official product instructions for chemical use, electrical work, plumbing repairs, and equipment compatibility."}, {"type": "heading", "text": "Unscored lesson practice — RF-102-P04"}, {"type": "paragraph", "text": "Question: A customer asks for “string for my weed eater.” What product term may help you begin the search?"}, {"type": "bullet", "text": "A. Roller cover."}, {"type": "bullet", "text": "B. Trimmer line."}, {"type": "bullet", "text": "C. Supply line."}, {"type": "bullet", "text": "D. Caulk."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: Trimmer line is a common product name for the cutting line used by certain string trimmers. Confirm the model and compatible line size."}, {"type": "paragraph", "text": "Scoring: Unscored. The answer and explanation appear after the question."}]}, {"id": "5354490f-656e-5cce-b202-ecfc6c7ca65f", "position": 5, "title": "Clear Communication and Smart Questions", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Knowing a term is only part of the job. Clear communication helps coworkers act on the right information. It also helps customers avoid buying the wrong item."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Be specific"}, {"type": "paragraph", "text": "Instead of “We need more of those,” say “The one-inch paint brushes are low on the shelf in aisle four.” Instead of “The order is here,” say “The system shows the special order as received. I will verify it before contacting the customer.”"}, {"type": "heading", "text": "Use a simple question pattern"}, {"type": "paragraph", "text": "Ask what the customer needs to do. Ask where the product will be used. Ask which size, model, or material is involved. Ask whether they have the old part, package, or instructions. One clear question is better than several guesses."}, {"type": "heading", "text": "Know the limits of a term"}, {"type": "paragraph", "text": "Words like universal, standard, and heavy-duty may appear on packages. They do not prove that a product fits every project. Read the manufacturer’s specifications. If a term is unclear, say what you know and what you still need to check."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer says, “I need a universal blade for this saw.” The employee asks for the saw model and the type of work. They check the blade specifications and seek help before recommending a product."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Use exact product names and location details when possible."}, {"type": "bullet", "text": "Tell customers when a detail still needs verification."}, {"type": "bullet", "text": "Pass clear notes to the next employee."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Using vague words like “that one” without a product description. Name the item."}, {"type": "bullet", "text": "Assuming “universal” means guaranteed compatibility. Check the specifications."}, {"type": "bullet", "text": "Pretending to understand an unfamiliar term. Ask for clarification."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a manager or specialist when a product label, model number, or safety claim is unclear. Refer regulated work to a qualified professional as appropriate."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Use exact product names and location details when possible."}, {"type": "bullet", "text": "Tell customers when a detail still needs verification."}, {"type": "bullet", "text": "Ask a manager or specialist when a product label, model number, or safety claim is unclear."}, {"type": "heading", "text": "Unscored lesson practice — RF-102-P05"}, {"type": "paragraph", "text": "Question: A customer asks for a “universal” saw blade. What is the best first step?"}, {"type": "bullet", "text": "A. Promise that any blade marked universal will fit."}, {"type": "bullet", "text": "B. Ask for the saw model and check blade compatibility."}, {"type": "bullet", "text": "C. Pick the least expensive blade."}, {"type": "bullet", "text": "D. Tell the customer all blades work the same way."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: Marketing terms do not replace compatibility checks. Confirm the saw model and blade specifications."}, {"type": "paragraph", "text": "Scoring: Unscored. The answer and explanation appear after the question."}]}], "questions": [{"id": "4b8c29ab-2084-577d-8a25-590242a2aeee", "position": 1, "prompt": "A coworker asks you to find a product by SKU. What should you look for?", "options": ["The store’s item identifier.", "The customer’s receipt number.", "The aisle cleaning schedule.", "The supplier’s phone number."], "correct_option": 0, "explanation": "A SKU is an identifier used by the store to track an item. It is not a receipt or a phone number."}, {"id": "6d3bb220-629f-5b0b-bbcd-2d3946ce3a39", "position": 2, "prompt": "A customer needs a replacement screw. Which information helps you find a match?", "options": ["The brand of the shopping basket.", "The shelf color and price alone.", "The screw’s size and thread information.", "The day the customer bought the old screw."], "correct_option": 2, "explanation": "A replacement screw must match important dimensions and thread details. Appearance and price do not confirm a fit."}, {"id": "cdc0ae11-69f4-5c6f-94a2-5ac0a5eae4ae", "position": 3, "prompt": "A customer asks for “the string for my weed eater.” Which product should you ask about?", "options": ["A paint roller cover.", "Trimmer line.", "Electrical supply wire.", "Plumbing coupling."], "correct_option": 1, "explanation": "Trimmer line is the product name that may match the customer’s description. Check the equipment model and compatible size."}, {"id": "76cdf837-79bd-524d-8c1c-b741c81c3237", "position": 4, "prompt": "Which message gives a coworker the clearest stock update?", "options": ["“Those things are gone.”", "“We need stuff over there.”", "“The item is probably somewhere.”", "“The two-inch paint brushes are low in aisle four.”"], "correct_option": 3, "explanation": "The clearest message names the item and location. Vague descriptions can cause delays and mistakes."}, {"id": "1246caa2-cb92-545f-8d62-13c9b7523d14", "position": 5, "prompt": "A customer asks whether a blade labeled “universal” fits their saw. What should you do?", "options": ["Say it fits every saw because of the label.", "Check the saw model and blade specifications before recommending it.", "Choose any blade with the same package color.", "Tell the customer that all blades have the same mounting system."], "correct_option": 1, "explanation": "A word like “universal” does not prove compatibility. Check manufacturer specifications and ask for help when needed."}]}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'RF-102 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'RF-102 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'RF-102 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'RF-102 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
end;
$courseimport$;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "df3b37e8-d81d-5b5e-b1db-003fcaf46759", "slug": "rf-103-store-safety-fundamentals", "version": 1, "title": "Store Safety Fundamentals", "description": "Learn to spot common hazards, work safely, and report concerns in a hardware store.", "category": "Retail Foundations", "passing_percent": 80}, "lessons": [{"id": "e62fd1be-4555-5882-b4e3-dfd311cc6c73", "position": 1, "title": "Spot Hazards Before They Cause Problems", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A small problem can become a serious injury. A loose box, blocked aisle, or wet floor can affect customers and coworkers."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Look at the path"}, {"type": "paragraph", "text": "Watch for spills, loose products, cords, and clutter. Keep walkways and exits clear."}, {"type": "heading", "text": "Recognize changing conditions"}, {"type": "paragraph", "text": "A busy delivery or crowded display can create a new hazard. Check your area as work changes."}, {"type": "heading", "text": "Protect the area"}, {"type": "paragraph", "text": "If a hazard is safe to address within your training, follow store procedures. If not, keep people away and alert the right person."}, {"type": "heading", "text": "Do not improvise"}, {"type": "paragraph", "text": "Do not handle unknown chemicals, damaged electrical items, or unstable loads without proper training and instructions."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "You notice a carton in a main aisle. A customer is walking toward it. You warn the customer, protect the area, and move the carton only if it is safe and allowed by store procedures."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Stay alert while walking through the store."}, {"type": "bullet", "text": "Warn others about an immediate hazard."}, {"type": "bullet", "text": "Follow store procedures to remove or isolate the hazard."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Walking past a hazard without reporting it."}, {"type": "bullet", "text": "Trying to clean an unknown spill without knowing the substance."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a supervisor about hazards you cannot safely fix. Get help for unknown spills, damaged wiring, and unstable merchandise."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Watch for spills, loose products, cords, and clutter."}, {"type": "bullet", "text": "Follow store procedures to remove or isolate the hazard."}, {"type": "bullet", "text": "Ask for help when a task is outside your training."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "RF-103-L01-P01: A small liquid spill appears near the checkout. You do not know what spilled. What should you do first?"}, {"type": "bullet", "text": "A. Ignore it until the next cleaning round."}, {"type": "bullet", "text": "B. Warn others, keep the area clear, and notify the appropriate employee."}, {"type": "bullet", "text": "C. Touch the liquid to identify it."}, {"type": "bullet", "text": "D. Cover it with merchandise."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: Unknown liquids may be hazardous. Protect people and follow the store's spill response process."}]}, {"id": "009d1a84-d337-56c8-ab70-81349f89bd20", "position": 2, "title": "Lift, Move, and Store Merchandise Safely", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Hardware stores carry heavy, sharp, and awkward products. A rushed move can hurt someone or damage merchandise."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Plan before lifting"}, {"type": "paragraph", "text": "Check the item's size, shape, and path. Decide whether you need help or approved equipment."}, {"type": "heading", "text": "Use a stable movement"}, {"type": "paragraph", "text": "Keep a secure grip and avoid sudden twisting. Do not carry a load that blocks your view."}, {"type": "heading", "text": "Ask for help"}, {"type": "paragraph", "text": "Use team lifting or approved material-handling equipment when a load is too heavy or awkward for you."}, {"type": "heading", "text": "Store with care"}, {"type": "paragraph", "text": "Keep heavy merchandise secure. Do not create unstable stacks or block aisles, exits, or emergency equipment."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer needs a large bag of concrete. The bag is awkward for you to move alone. You arrange help or use approved equipment instead of forcing the lift."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Check the load and the route."}, {"type": "bullet", "text": "Ask for help before lifting an awkward item."}, {"type": "bullet", "text": "Keep storage areas orderly and stable."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Lifting beyond your ability to save time."}, {"type": "bullet", "text": "Stacking products where they could fall."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask for help with heavy, sharp, oversized, or unstable items. Follow store rules for carts, ladders, and lifting devices."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Check the item's size, shape, and path."}, {"type": "bullet", "text": "Keep storage areas orderly and stable."}, {"type": "bullet", "text": "Ask for help when a task is outside your training."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "RF-103-L02-P01: A tall carton blocks your view while you carry it. What is the best choice?"}, {"type": "bullet", "text": "A. Keep walking slowly."}, {"type": "bullet", "text": "B. Lift it higher above your head."}, {"type": "bullet", "text": "C. Stop and arrange a safer way to move it."}, {"type": "bullet", "text": "D. Ask a customer to guide you."}, {"type": "paragraph", "text": "Answer: C"}, {"type": "paragraph", "text": "Explanation: You need a clear path and safe control of the load. Use help or approved equipment."}]}, {"id": "3a11614d-470d-5ae9-a8e4-5f274acae2ca", "position": 3, "title": "Know Your Limits with Tools and Equipment", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Stores may use ladders, cutters, powered equipment, and service tools. Familiar equipment can still cause injuries."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Use only authorized equipment"}, {"type": "paragraph", "text": "Complete required training before using powered equipment or specialized store tools."}, {"type": "heading", "text": "Check before use"}, {"type": "paragraph", "text": "Follow the store's inspection steps and the manufacturer's instructions. Report damaged tools or missing guards."}, {"type": "heading", "text": "Respect restricted areas"}, {"type": "paragraph", "text": "Stay outside marked work zones. Do not distract someone who is operating equipment."}, {"type": "heading", "text": "Stop when unsure"}, {"type": "paragraph", "text": "Do not guess about equipment operation or attempt repairs beyond your training."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A coworker asks you to use a powered pallet jack. You have not been trained or authorized. You decline and contact a qualified employee."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Check whether you are authorized."}, {"type": "bullet", "text": "Follow the equipment instructions and store procedures."}, {"type": "bullet", "text": "Report damage and stop unsafe work."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Using a machine because you have watched someone else use it."}, {"type": "bullet", "text": "Removing a guard to finish a job faster."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a supervisor before using unfamiliar equipment. Only trained and authorized people should perform restricted tasks."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Complete required training before using powered equipment or specialized store tools."}, {"type": "bullet", "text": "Report damage and stop unsafe work."}, {"type": "bullet", "text": "Ask for help when a task is outside your training."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "RF-103-L03-P01: You are asked to operate equipment you have never been trained to use. What should you do?"}, {"type": "bullet", "text": "A. Try it carefully with a coworker watching."}, {"type": "bullet", "text": "B. Watch an online video and begin."}, {"type": "bullet", "text": "C. Use it only for a short task."}, {"type": "bullet", "text": "D. Explain that you need training and an authorized operator."}, {"type": "paragraph", "text": "Answer: D"}, {"type": "paragraph", "text": "Explanation: Observation alone is not authorization. Use equipment only after the required training and approval."}]}, {"id": "54f7e84f-985f-59f5-8df0-55d37ab5b3eb", "position": 4, "title": "Respond to Spills, Injuries, and Emergencies", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Fast, calm action can protect people. Every store needs clear procedures for incidents and emergencies."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "For immediate danger"}, {"type": "paragraph", "text": "Move away from danger and alert others. Contact emergency services when needed, using local procedures."}, {"type": "heading", "text": "For an injury"}, {"type": "paragraph", "text": "Notify the designated person. Get emergency help for serious injuries. Do not provide care beyond your training."}, {"type": "heading", "text": "For a spill"}, {"type": "paragraph", "text": "Keep others away. Identify the substance only through safe, approved methods. Follow the store's spill procedure and safety information."}, {"type": "heading", "text": "For an alarm or evacuation"}, {"type": "paragraph", "text": "Follow the store's emergency plan. Use designated exits and assembly points. Do not block emergency responders."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer falls near a display and says they cannot stand. You alert the designated employee and request emergency help as appropriate. You do not move the customer unless immediate danger makes it necessary."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Know how to alert a manager and emergency responders."}, {"type": "bullet", "text": "Keep others away from danger."}, {"type": "bullet", "text": "Follow the store emergency plan."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Assuming someone else called for help."}, {"type": "bullet", "text": "Moving an injured person without a safety reason or proper training."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a manager for the store's emergency contacts, evacuation plan, and incident process. Emergency services should handle urgent medical or fire emergencies."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Move away from danger and alert others."}, {"type": "bullet", "text": "Follow the store emergency plan."}, {"type": "bullet", "text": "Ask for help when a task is outside your training."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "RF-103-L04-P01: A customer is seriously injured. Which action best fits your role?"}, {"type": "bullet", "text": "A. Follow the emergency plan, alert the designated person, and call for emergency help as needed."}, {"type": "bullet", "text": "B. Move the customer immediately to a chair."}, {"type": "bullet", "text": "C. Wait until the customer asks for help."}, {"type": "bullet", "text": "D. Post a message in the team chat first."}, {"type": "paragraph", "text": "Answer: A"}, {"type": "paragraph", "text": "Explanation: Use the store emergency plan and seek urgent help when needed. Do not move an injured person without a compelling safety reason."}]}, {"id": "e17dd363-2cb1-5a89-a488-ac33301f6bb5", "position": 5, "title": "Speak Up and Report Safety Concerns", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Reporting gives the team a chance to fix a problem before someone gets hurt. A near miss is an event that could have caused harm but did not."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Report promptly"}, {"type": "paragraph", "text": "Tell the appropriate person about hazards, injuries, damaged equipment, and near misses."}, {"type": "heading", "text": "Be specific"}, {"type": "paragraph", "text": "Describe what happened, where it happened, and what immediate action you took."}, {"type": "heading", "text": "Share facts"}, {"type": "paragraph", "text": "Do not guess about causes or blame people. Use the store's reporting process."}, {"type": "heading", "text": "Follow through"}, {"type": "paragraph", "text": "Confirm that the concern reached the right person. Do not assume a report means the area is now safe."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A stack of buckets shifts and nearly falls. No one is hurt. You keep the area clear and report the location, what moved, and what you observed."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Report near misses as well as injuries."}, {"type": "bullet", "text": "Give clear facts and a precise location."}, {"type": "bullet", "text": "Keep the area protected until the hazard is addressed."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Ignoring a near miss because nobody was hurt."}, {"type": "bullet", "text": "Guessing about the cause instead of sharing observations."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a manager which reporting form or channel your store uses. Escalate an unresolved immediate hazard right away."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Tell the appropriate person about hazards, injuries, damaged equipment, and near misses."}, {"type": "bullet", "text": "Keep the area protected until the hazard is addressed."}, {"type": "bullet", "text": "Ask for help when a task is outside your training."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "RF-103-L05-P01: A stack of merchandise almost falls, but no one is hurt. What should you do?"}, {"type": "bullet", "text": "A. Say nothing because there was no injury."}, {"type": "bullet", "text": "B. Report the near miss and keep people away from the unstable stack."}, {"type": "bullet", "text": "C. Wait for the next staff meeting."}, {"type": "bullet", "text": "D. Restack it alone without checking the cause."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: A near miss is useful safety information. Report it and protect the area."}]}], "questions": [{"id": "7614494c-e55d-524b-991f-891cca280928", "position": 1, "prompt": "You see a loose cord across an aisle. A shopper is approaching. What is your best first action?", "options": ["Step over it and continue working.", "Warn the shopper, keep the area clear, and follow the store's process to address it.", "Wait for the closing team.", "Move a display in front of it without telling anyone."], "correct_option": 1, "explanation": "A visible trip hazard needs prompt attention. Warn others and follow the approved response."}, {"id": "4b2eb405-2c46-5bfc-8f5e-697c371cb153", "position": 2, "prompt": "You need to move an awkward box. You cannot see over it when carrying it. What should you do?", "options": ["Carry it slowly and hope the aisle stays clear.", "Ask a customer to carry one side.", "Use help or approved equipment to move it safely.", "Hold it above your head."], "correct_option": 2, "explanation": "Keep control of the load and a clear view of the route. Ask for help or use approved equipment."}, {"id": "02914b8b-caa7-5d24-99cd-061bb5427fd2", "position": 3, "prompt": "A coworker asks you to use a store machine. You have not completed the required training. What should you do?", "options": ["Decline and ask for an authorized operator or training.", "Try the controls with no load.", "Use it if the manager is busy.", "Copy what you saw another employee do."], "correct_option": 0, "explanation": "Powered or specialized equipment requires the appropriate training and authorization."}, {"id": "72a34295-5dd2-5583-b5f8-4cfd08a3965b", "position": 4, "prompt": "A customer collapses near the front counter. What is the best response?", "options": ["Offer water before telling anyone.", "Move the customer to a chair immediately.", "Wait for the customer to recover.", "Follow the emergency plan and call for emergency help as needed."], "correct_option": 3, "explanation": "Follow the emergency plan and seek emergency help promptly. Do not move the person unless necessary for immediate safety."}, {"id": "d2ab29f9-a04a-52f1-a148-e274e8508ab9", "position": 5, "prompt": "A shelf bracket bends, but no product falls and no one is injured. What should you do?", "options": ["Ignore it because nothing fell.", "Report the near miss, describe the location, and keep the area protected.", "Fix it without reporting it.", "Tell a coworker later if you remember."], "correct_option": 1, "explanation": "Near misses should be reported. Clear facts help the store address hazards before injuries occur."}]}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'RF-103 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'RF-103 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'RF-103 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'RF-103 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
end;
$courseimport$;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "57d15a1b-42bf-5b91-b376-e82d787fef8c", "slug": "rf-104-understanding-the-hardware-store", "version": 1, "title": "Understanding the Hardware Store", "description": "Learn how a hardware store is organized. Find the right department, follow basic product flow, and connect customers with the right help.", "category": "Retail Foundations", "passing_percent": 80}, "lessons": [{"id": "57c6dafd-b94e-5c78-be50-53d9f25ee03a", "position": 1, "title": "Find Your Way Around the Store", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers expect employees to help them find products. A clear picture of the store makes that easier."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Common store areas"}, {"type": "paragraph", "text": "Most hardware stores have a sales floor, checkout area, receiving area, stockroom, and service counter. Some stores also have a garden center or rental desk. Store layouts vary."}, {"type": "heading", "text": "The sales floor"}, {"type": "paragraph", "text": "The sales floor is where customers shop. Products are often grouped by department. Aisles may include paint, plumbing, electrical, tools, hardware, and lawn and garden."}, {"type": "heading", "text": "Areas behind the scenes"}, {"type": "paragraph", "text": "Receiving is where deliveries are checked. A stockroom holds merchandise that is not on the sales floor. Employees should enter restricted areas only with permission."}, {"type": "heading", "text": "Store maps and signs"}, {"type": "paragraph", "text": "Aisle signs, shelf labels, and store maps can help you locate merchandise. Confirm the location when signs and inventory records do not agree."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks for weatherstripping. You know it may be near doors or insulation. You check the store directory and guide the customer to the correct area."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Learn the names of your store’s main departments."}, {"type": "bullet", "text": "Locate checkout, receiving, and customer service areas."}, {"type": "bullet", "text": "Use approved store maps or coworkers to verify locations."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Assuming every hardware store uses the same layout."}, {"type": "bullet", "text": "Sending a customer to an aisle without checking."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a coworker when a department or restricted area is unfamiliar."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Know the main store areas."}, {"type": "bullet", "text": "Use signs and approved resources."}, {"type": "bullet", "text": "Verify locations before directing customers."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question (RF-104-L01-P01): A customer asks for an item in a department you have not visited. What should you do?"}, {"type": "paragraph", "text": "Answer: Check the store map or ask a coworker. Then guide the customer to the correct area."}, {"type": "paragraph", "text": "Explanation: Store layouts vary. Verification is better than guessing."}]}, {"id": "57193363-5dbc-5e6b-9190-0b5c926b4144", "position": 2, "title": "Understand the Main Departments", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers often describe a project instead of a product. Department knowledge helps you decide where to start."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Hardware and fasteners"}, {"type": "paragraph", "text": "This area often includes screws, bolts, nuts, washers, hinges, and other small parts. Size and material matter."}, {"type": "heading", "text": "Tools and power equipment"}, {"type": "paragraph", "text": "Hand tools include hammers, wrenches, and screwdrivers. Power tools include drills and saws. Outdoor power equipment may have its own department."}, {"type": "heading", "text": "Home repair departments"}, {"type": "paragraph", "text": "Plumbing often includes pipe, fittings, and repair parts. Electrical may include switches, outlets, and lighting products. Paint may include coatings, brushes, rollers, and preparation supplies."}, {"type": "heading", "text": "Lawn, garden, and building materials"}, {"type": "paragraph", "text": "Lawn and garden may carry soil, seeds, fertilizers, and hoses. Building materials may include lumber, sheet goods, and concrete products. Not every store carries every category."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer wants to repair a dripping outdoor faucet. You recognize this as a plumbing question. You guide the customer to the plumbing area and help find an experienced associate."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Learn two common product groups in each department."}, {"type": "bullet", "text": "Ask customers what project they are completing."}, {"type": "bullet", "text": "Refer detailed product questions to trained coworkers."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Assuming a product belongs in only one department."}, {"type": "bullet", "text": "Confusing similar-looking parts."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a department specialist before recommending technical parts or products with safety requirements."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Learn the purpose of each department."}, {"type": "bullet", "text": "Listen for the customer’s project."}, {"type": "bullet", "text": "Do not guess about technical product fit."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question (RF-104-L02-P01): A customer asks for a roller cover and painter’s tape. Which department is a good starting point?"}, {"type": "paragraph", "text": "Answer: Paint and decorating."}, {"type": "paragraph", "text": "Explanation: Both items are commonly used for painting projects."}]}, {"id": "d41accd1-52ed-50a4-b5db-21751afde17a", "position": 3, "title": "Follow a Product Through the Store", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Products must move through several steps before customers can buy them. Each step affects accuracy and availability."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Receiving"}, {"type": "paragraph", "text": "A delivery arrives at the store. Authorized employees check the shipment against the store’s receiving process. They report shortages or damage."}, {"type": "heading", "text": "Storage and stocking"}, {"type": "paragraph", "text": "Products may go directly to shelves or into backstock. Backstock means extra merchandise kept off the sales floor. Products need accurate locations and labels."}, {"type": "heading", "text": "Selling and replenishment"}, {"type": "paragraph", "text": "Customers buy products at checkout or through another approved sales channel. Sales and other inventory changes may update the store’s inventory records. The timing depends on the system."}, {"type": "heading", "text": "Returns and exceptions"}, {"type": "paragraph", "text": "Returns, damaged goods, and special orders follow store-specific procedures. Do not put returned items back on shelves without following those procedures."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer wants a box of deck screws. The shelf is empty. The inventory record shows available stock. You ask an authorized coworker to check the backstock location before making a promise."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Keep product labels with the correct merchandise."}, {"type": "bullet", "text": "Report damage and quantity differences."}, {"type": "bullet", "text": "Use the store’s approved receiving and return procedures."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Treating an inventory count as proof that an item is on the shelf."}, {"type": "bullet", "text": "Putting unverified merchandise into saleable stock."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask receiving or inventory staff when counts, locations, or product condition do not match."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Products move from receiving to storage or shelves."}, {"type": "bullet", "text": "Accurate locations help customers."}, {"type": "bullet", "text": "Exceptions need approved procedures."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question (RF-104-L03-P01): The shelf is empty, but the system lists two items. Is the item definitely available?"}, {"type": "paragraph", "text": "Answer: No. Check the location and ask the appropriate employee to verify."}, {"type": "paragraph", "text": "Explanation: Inventory records can differ from physical stock."}]}, {"id": "d3129140-4f73-5b39-9135-23f20335567c", "position": 4, "title": "Know Common Store Services", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Many customers visit hardware stores for services as well as products. Services differ by location."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Services vary by store"}, {"type": "paragraph", "text": "Some stores offer key cutting, paint mixing, screen repair, propane exchange, delivery, or equipment service. These are examples, not promises about every store."}, {"type": "heading", "text": "Ask before promising"}, {"type": "paragraph", "text": "Services may require trained staff, special equipment, or scheduled hours. Confirm availability, pricing, and turnaround time through approved store resources."}, {"type": "heading", "text": "Understand your role"}, {"type": "paragraph", "text": "You may greet the customer, gather basic details, or direct them to the correct counter. Only trained and authorized employees should operate service equipment."}, {"type": "heading", "text": "Set clear expectations"}, {"type": "paragraph", "text": "Tell customers what has been confirmed. Avoid promising that a service can be completed immediately unless an authorized employee has verified it."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks whether the store can cut a replacement key today. You check the service list and ask the trained employee about availability. You then explain the next step."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Learn which services your store actually offers."}, {"type": "bullet", "text": "Find out who is authorized to perform each service."}, {"type": "bullet", "text": "Verify hours, pricing, and timelines before making promises."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Assuming every location offers the same services."}, {"type": "bullet", "text": "Operating service equipment without training."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask the service lead or manager when availability, pricing, or authorization is unclear."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Services differ by store."}, {"type": "bullet", "text": "Verify details before promising."}, {"type": "bullet", "text": "Use trained staff for service equipment."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question (RF-104-L04-P01): A customer asks for same-day screen repair. You do not know the schedule. What should you say?"}, {"type": "paragraph", "text": "Answer: Let me check whether we offer that service and what the current turnaround time is."}, {"type": "paragraph", "text": "Explanation: Confirm service availability before setting expectations."}]}, {"id": "62e54d5f-72f0-55a2-b5ee-4c4d36ea24a6", "position": 5, "title": "Connect Customers With the Right Help", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "You do not need to know every product or service. You do need to help customers reach the right resource."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Start with the need"}, {"type": "paragraph", "text": "Listen to the customer’s project or request. Repeat the key detail in simple words to confirm your understanding."}, {"type": "heading", "text": "Choose a resource"}, {"type": "paragraph", "text": "Use aisle signs for locations. Use approved inventory tools for stock checks. Use service lists for store services. Ask trained coworkers about specialized products."}, {"type": "heading", "text": "Make a useful handoff"}, {"type": "paragraph", "text": "A handoff means passing a customer request to another employee. Share the important facts. Do not make the customer repeat the whole story when you can help."}, {"type": "heading", "text": "Follow through"}, {"type": "paragraph", "text": "Confirm that the customer has reached the right person or next step. Do not leave a customer waiting without an update."}, {"type": "heading", "text": "Know when to stop"}, {"type": "paragraph", "text": "Do not give instructions for licensed work or make unsupported safety claims. Refer technical questions to qualified people and approved manufacturer guidance."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer needs a part for a ceiling fan. You ask for the model information. You connect the customer with an associate who can check compatible replacement parts. You share the model details during the handoff."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Listen and confirm the customer’s request."}, {"type": "bullet", "text": "Choose the right department, resource, or trained coworker."}, {"type": "bullet", "text": "Share useful details during a handoff."}, {"type": "bullet", "text": "Confirm the next step with the customer."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Guessing a product location or fit."}, {"type": "bullet", "text": "Pointing vaguely across the store."}, {"type": "bullet", "text": "Leaving the customer without a clear next step."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a manager or trained coworker when the request involves technical compatibility, service promises, or safety."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Listen before directing."}, {"type": "bullet", "text": "Use the right store resource."}, {"type": "bullet", "text": "Give clear handoffs."}, {"type": "bullet", "text": "Confirm the next step."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question (RF-104-L05-P01): You cannot identify a replacement part. What information should you share with a specialist?"}, {"type": "paragraph", "text": "Answer: Share the customer’s project, the old part or model details, and what you have already checked."}, {"type": "paragraph", "text": "Explanation: A clear handoff saves time and reduces confusion."}]}], "questions": [{"id": "bb22a016-4614-5dda-a23c-353ac2254d09", "position": 1, "prompt": "A customer asks where to find a product. You do not know the aisle. What is the best next step?", "options": ["Guess the most likely aisle.", "Check an approved store map or ask a coworker.", "Tell the customer to search every aisle.", "Send the customer to receiving."], "correct_option": 1, "explanation": "Store layouts vary. Use an approved resource or coworker to confirm the location."}, {"id": "ec8a61a5-c219-5416-9db4-f9f7799d8c6a", "position": 2, "prompt": "A customer needs a roller cover and painter’s tape. Where should you start?", "options": ["Plumbing.", "Electrical.", "Paint and decorating.", "Outdoor power equipment."], "correct_option": 2, "explanation": "Roller covers and painter’s tape are common paint supplies."}, {"id": "1c10b554-080c-5ee2-b9aa-65a9a3ed593d", "position": 3, "prompt": "The shelf is empty, but the inventory record shows stock. What should you do?", "options": ["Promise the customer the item is available.", "Change the count to zero without checking.", "Tell the customer inventory records are always wrong.", "Check approved stock locations or ask an authorized coworker to verify."], "correct_option": 3, "explanation": "A system quantity is not proof of physical availability. Verify before making a promise."}, {"id": "5e687190-7cba-508b-be2d-14c2d10dd221", "position": 4, "prompt": "A customer asks for a service you have never seen offered at your store. What should you do?", "options": ["Confirm the service list and ask authorized staff before promising it.", "Promise the service and decide who will do it later.", "Try the service equipment without training.", "Say every hardware store offers the same services."], "correct_option": 0, "explanation": "Store services differ. Verify availability and use trained staff."}, {"id": "cc6e7da4-b740-556a-a826-5039327190b7", "position": 5, "prompt": "You bring a customer to a department specialist. Which handoff is best?", "options": ["Leave without speaking.", "Tell the specialist only that the customer needs help.", "Share the customer’s project and the details already collected.", "Ask the customer to restart the conversation from the beginning."], "correct_option": 2, "explanation": "A useful handoff shares relevant facts and helps the next employee continue the work."}]}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'RF-104 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'RF-104 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'RF-104 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'RF-104 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
end;
$courseimport$;
commit;
select slug,title,published,(select count(*) from public.training_lessons where course_id=c.id) as lessons,(select count(*) from public.training_questions where course_id=c.id) as quiz_questions from public.training_courses c where id in ('b24247d7-0237-51ca-9f36-82037a9cc61d','df3b37e8-d81d-5b5e-b1db-003fcaf46759','57d15a1b-42bf-5b91-b376-e82d787fef8c') order by slug;
